<!doctype html>
<html lang="en"><?php include '../include/page-config.php'; require_once '../data/demo-data.php'; include '../include/head.php'; ?>
<body class="layout-fixed sidebar-expand-lg bg-body-tertiary"><div class="app-wrapper"><?php include '../layout/header.php'; include '../layout/sidebar.php'; ?><main class="app-main"><?php include '../layout/page-header.php'; ?><div class="app-content"><div class="container-fluid"><?php $selected=(int)($_GET['customer']??2);$customer=$demoCustomers[0];foreach($demoCustomers as $c){if((int)$c['id']===$selected){$customer=$c;break;}}$selected=(int)$customer['id'];$summary=$demoCustomerSummary[$selected]??['total_sales'=>0,'total_paid'=>0,'outstanding'=>0,'invoice_count'=>0,'last_sale_date'=>'—'];$entries=$demoCustomerLedger[$selected]??[]; ?><div class="card"><div class="card-header"><h3 class="card-title">Customer ledger</h3><select class="form-select form-select-sm ms-auto" style="max-width:240px" onchange="location.href='customer-ledger.php?customer='+this.value"><?php foreach($demoCustomers as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$c['id']===$selected?'selected':'' ?>><?= htmlspecialchars($c['customer_name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="card-body"><div class="row g-3 mb-3"><div class="col-md-3"><div class="border rounded p-3"><div class="small text-body-secondary">Customer</div><strong><?= htmlspecialchars($customer['customer_name'],ENT_QUOTES,'UTF-8') ?></strong></div></div><div class="col-md-3"><div class="border rounded p-3"><div class="small text-body-secondary">Total Sales</div><strong>Rs. <?= number_format($summary['total_sales'],2) ?></strong></div></div><div class="col-md-3"><div class="border rounded p-3"><div class="small text-body-secondary">Payments Received</div><strong>Rs. <?= number_format($summary['total_paid'],2) ?></strong></div></div><div class="col-md-3"><div class="border rounded p-3"><div class="small text-body-secondary">Outstanding Balance</div><strong>Rs. <?= number_format($summary['outstanding'],2) ?></strong></div></div></div><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th class="text-end">Debit</th><th class="text-end">Credit</th><th class="text-end">Balance</th></tr></thead><tbody><?php if(!$entries): ?><tr><td colspan="6" class="text-center text-body-secondary">No sales or payment transactions for this customer.</td></tr><?php else: foreach($entries as $entry): ?><tr><td><?= htmlspecialchars($entry['date'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($entry['reference'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($entry['description'],ENT_QUOTES,'UTF-8') ?></td><td class="text-end"><?= $entry['debit'] ? 'Rs. '.number_format($entry['debit'],2) : '—' ?></td><td class="text-end"><?= $entry['credit'] ? 'Rs. '.number_format($entry['credit'],2) : '—' ?></td><td class="text-end fw-semibold">Rs. <?= number_format($entry['balance'],2) ?></td></tr><?php endforeach; endif; ?></tbody><tfoot><tr><th colspan="5" class="text-end">Closing Balance</th><th class="text-end">Rs. <?= number_format($summary['outstanding'],2) ?></th></tr></tfoot></table></div><p class="small text-body-secondary mb-0">Debits represent sales invoices; credits represent payments collected against those invoices. This is illustrative demo data.</p></div></div></div></div></main><?php include '../layout/footer.php'; ?></div><?php include '../include/footer-scripts.php'; ?></body></html>